create or replace function public.set_bill_payment_status(p_payment_id uuid,p_status text) returns public.bill_payments language plpgsql security definer set search_path=public as $$ declare a public.profiles%rowtype;p public.bill_payments%rowtype;s text:=case when p_status='not_received' then 'rejected' else p_status end;begin select * into a from public.profiles where id=auth.uid() and role='admin' and status='active' and canteen_id=public.current_canteen_id();if not found then raise exception 'Admin authorization required';end if;if s not in('paid','rejected') then raise exception 'Invalid payment status';end if;select * into p from public.bill_payments where id=p_payment_id and canteen_id=public.current_canteen_id();if not found then raise exception 'Payment record not found';end if;if p.status<>'pending_verification' then raise exception 'Only pending verification payments can be resolved';end if;update public.bill_payments set status=s,approved_at=case when s='paid' then now() else null end,approved_by=case when s='paid' then auth.uid() else null end,updated_at=now() where id=p.id returning * into p;insert into public.notifications(recipient_id,notification_type,title,message,payload,created_at,canteen_id) values(p.employee_id,'payment_status_updated',case when s='paid' then 'Payment Received' else 'Payment Rejected' end,case when s='paid' then 'Your payment has been verified as received.' else 'Your payment was not received. Please make the outstanding payment again.' end,jsonb_build_object('bill_id',p.bill_id,'payment_id',p.id,'status',s,'amount',p.amount,'payment_reference',p.payment_reference),now(),p.canteen_id);return p;end;$$;